import { MakeLogicType, afterMount, connect, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { projectLogic } from 'scenes/projectLogic'

import { tasksMeAgentPreferencesCreate, tasksMeAgentPreferencesList } from 'products/tasks/frontend/generated/api'
import type {
    TasksAgentPreferencesApi,
    TasksAgentPreferencesUpdateApi,
} from 'products/tasks/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface agentPreferencesLogicValues {
    currentProjectId: number | null // projectLogic
    agentPreferences: TasksAgentPreferencesApi | null
    agentPreferencesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface agentPreferencesLogicActions {
    loadAgentPreferences: () => any
    loadAgentPreferencesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadAgentPreferencesSuccess: (
        agentPreferences: TasksAgentPreferencesApi | null,
        payload?: any
    ) => {
        agentPreferences: TasksAgentPreferencesApi | null
        payload?: any
    }
    saveAgentPreferences: (changes: TasksAgentPreferencesUpdateApi) => TasksAgentPreferencesUpdateApi
    saveAgentPreferencesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    saveAgentPreferencesSuccess: (
        agentPreferences: TasksAgentPreferencesApi | null,
        payload?: TasksAgentPreferencesUpdateApi
    ) => {
        agentPreferences: TasksAgentPreferencesApi | null
        payload?: TasksAgentPreferencesUpdateApi
    }
}

export type agentPreferencesLogicType = MakeLogicType<agentPreferencesLogicValues, agentPreferencesLogicActions>

export const agentPreferencesLogic = kea<agentPreferencesLogicType>([
    path(['products', 'posthog_ai', 'frontend', 'logics', 'agentPreferencesLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),
    loaders(({ values }) => ({
        agentPreferences: [
            null as TasksAgentPreferencesApi | null,
            {
                loadAgentPreferences: async (): Promise<TasksAgentPreferencesApi | null> => {
                    if (values.currentProjectId == null) {
                        return null
                    }
                    try {
                        return await tasksMeAgentPreferencesList(String(values.currentProjectId))
                    } catch {
                        return null
                    }
                },
                saveAgentPreferences: async (
                    changes: TasksAgentPreferencesUpdateApi
                ): Promise<TasksAgentPreferencesApi | null> => {
                    if (values.currentProjectId == null) {
                        return values.agentPreferences
                    }
                    try {
                        const saved = await tasksMeAgentPreferencesCreate(String(values.currentProjectId), changes)
                        lemonToast.success('Task defaults saved')
                        return saved
                    } catch {
                        lemonToast.error('Your task defaults did not save. Try again.')
                        return values.agentPreferences
                    }
                },
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadAgentPreferences()
    }),
])
